void initialize_ncurses() {
  signal(2, finish);
  initscr();
  keypad(stdscr, 1);
  nonl();
  intrflush(stdscr, 0);
  noecho();
  cbreak();
  if (has_colors()) {
      start_color();
      init_pair(0, 0, 0);
      init_pair(2, 2, 0);
      init_pair(1, 1, 0);
      init_pair(6, 6, 0);
      init_pair(7, 7, 0);
      init_pair(5, 5, 0);
      init_pair(4, 4, 0);
      init_pair(3, 3, 0);
    }
}

void initialize_arrays() {
  int counter, counter2;
  screen_object empty;
  int i = 0;
  screen = malloc (sizeof (int*) * ((COLS - 1) + 1));
  for (i = 0; i < ((COLS - 1) + 1); ++i) {
          screen[i] = malloc (sizeof (int) * ((LINES - 1) + 1));
  }
  empty.x = -1;
  empty.y = -1;
  empty.color = 0;
  empty.bold = 0;
  empty.character = ' ';
  for (counter = 0; counter <= (COLS - 1); counter++) {
      for (counter2 = 0; counter2 <= (LINES - 1); counter2++) {
   screen[counter][counter2] = -1;
 }
    }
  for (counter = 0; counter < (sizeof messages / sizeof (char*)); counter++) {
      used_messages[counter] = 0;
      bogus_messages[counter] = 0;
      bogus[counter] = empty;
    }
}

void initialize_robot() {
  robot.x = rand() % (COLS - 1)+1;
  robot.y = rand() % ((LINES - 1)-3 +1)+3;
  robot.character = '#';
  robot.color = 0;
  robot.bold = 0;
  screen[robot.x][robot.y] = 0;
}

void initialize_kitten() {
  do {
      kitten.x = rand() % (COLS - 1)+1;
      kitten.y = rand() % ((LINES - 1)-3 +1)+3;
    } while (screen[kitten.x][kitten.y] != -1);
  do {
    kitten.character = rand() % (126-'!'+1)+'!';;
  } while (!(validchar(kitten.character)));
  screen[kitten.x][kitten.y] = 1;
  kitten.color = rand() % 6 + 1;
  kitten.bold = (rand() % 2 ? 1:0);
}

void initialize_bogus() {
  int counter, index;
  for (counter = 0; counter < num_bogus; counter++) {
      bogus[counter].color = rand() % 6 + 1;
      bogus[counter].bold = (rand() % 2 ? 1:0);
      do {
 bogus[counter].character = rand() % (126-'!'+1)+'!';;
      } while (!(validchar(bogus[counter].character)));
      do {
   bogus[counter].x = rand() % (COLS - 1)+1;
   bogus[counter].y = rand() % ((LINES - 1)-3 +1)+3;
 } while (screen[bogus[counter].x][bogus[counter].y] != -1);
      screen[bogus[counter].x][bogus[counter].y] = counter+2;
      do {
 index = rand() % (sizeof messages / sizeof (char*));
      } while (used_messages[index] != 0);
      bogus_messages[counter] = index;
      used_messages[index] = 1;
    }
}

void initialize_screen() {
  int counter;
  mvprintw(0,0,"robotfindskitten v%s\n\n",ver);
  for (counter = 0; counter <= (COLS - 1); counter++) {
      printw("%c",95);
    }
  for (counter = 0; counter < num_bogus; counter++) {
      draw(bogus[counter]);
    }
  draw(kitten);
  draw(robot);
  wrefresh(stdscr);
}

void instructions() {
  char dummy;
  mvprintw(0,0,"robotfindskitten v%s\n",ver);
  printw("By the illustrious Leonard Richardson (C) 1997, 2000\n");
  printw("Written originally for the Nerth Pork robotfindskitten contest\n\n");
  printw("In this game, you are robot (");
  draw_in_place(robot);
  printw("). Your job is to find kitten. This task\n");
  printw("is complicated by the existence of various things which are not kitten.\n");
  printw("Robot must touch items to determine if they are kitten or not. The game\n");
  printw("ends when robotfindskitten. Alternatively, you may end the game by hitting\n");
  printw("the Esc key. See the documentation for more information.\n\n");
  printw("Press any key to start.\n");
  wrefresh(stdscr);
  dummy = wgetch(stdscr);
  wclear(stdscr);
}

void finish(int sig) {
    endwin();
    printf("%c%c%c",27,'(','B');
    exit(0);
}

void play_game() {
  int old_x = robot.x;
  int old_y = robot.y;
  int input;
  input = wgetch(stdscr);
  while ((input != 27) && (input != 'q') && (input != 'Q')) {
      process_input(input);
      if (!(old_x == robot.x && old_y == robot.y)) {
   (wmove((stdscr),((old_y)),((old_x))) == (-1) ? (-1) : waddch((stdscr),((' '))));
   screen[old_x][old_y] = -1;
   draw(robot);
   wrefresh(stdscr);
   screen[robot.x][robot.y] = 0;
   old_x = robot.x;
   old_y = robot.y;
 }
      input = wgetch(stdscr);
    }
  message("Bye!");
  wrefresh(stdscr);
  finish(0);
}

void process_input(int input) {
  int check_x = robot.x;
  int check_y = robot.y;
  switch (input) {
    case ('L' - 64): wrefresh(curscr);
      break;
    case 0403: case 'k': case 'K': case ('P' - 64): check_y--;
      break;
    case 0406: case 'y': case 'Y': check_x--;
      check_y--;
      break;
    case 0523: case 'u': case 'U': check_x++;
      check_y--;
      break;
    case 0402: case 'j': case 'J': case ('N' - 64): check_y++;
      break;
    case 0550: case 'b': case 'B': check_x--;
      check_y++;
      break;
    case 0522: case 'n': case 'N': check_x++;
      check_y++;
      break;
    case 0404: case 'h': case 'H': case ('B' - 64): check_x--;
      break;
    case 0405: case 'l': case 'L': case ('F' - 64): check_x++;
      break;
    case 0: break;
    default: message("Invalid input: Use direction keys or Esc.");
      return;
    }
  if (check_y < 3 || check_y > (LINES - 1) || check_x < 0 || check_x > (COLS - 1)) {
      return;
    }
  if (screen[check_x][check_y] != -1) {
      switch (screen[check_x][check_y]) {
 case 0: break;
 case 1: wmove(stdscr,(1),(0));
   wclrtoeol(stdscr);
   play_animation(input);
   break;
 default: message(messages[bogus_messages[screen[check_x][check_y]-2]]);
   break;
 }
      return;
    }
  robot.x = check_x;
  robot.y = check_y;
}

int validchar(char a) {
  switch(a) {
    case '#': case ' ': case 127: return 0;
    }
  return 1;
}

void play_animation(int input) {
  int counter;
  for (counter = 4; counter >0; counter--) {
      (wmove((stdscr),((1)),((50 +counter+1))) == (-1) ? (-1) : waddch((stdscr),((' '))));
      wmove(stdscr,(1),(50 +counter));
      if (input == 0405 || input == 0402 || input == 0540 || input == 0535) draw_in_place(kitten);
      else draw_in_place(robot);
      (wmove((stdscr),((1)),((50 -counter))) == (-1) ? (-1) : waddch((stdscr),((' '))));
      wmove(stdscr,(1),(50 -counter+1));
      if (input == 0405 || input == 0402 || input == 0540 || input == 0535) draw_in_place(robot);
      else draw_in_place(kitten);
      wrefresh(stdscr);
      sleep (1);
    }
  wmove(stdscr,(1),(0));
  waddnstr(stdscr,("You found kitten! Way to go, robot!"),-1);
  wrefresh(stdscr);
  finish(0);
}

void full_draw(screen_object o, _Bool in_place) {
  attr_t old;
  short dummy;
  attr_t new;
  wattr_get(stdscr,(&old),(&dummy),(0));
  new = (((chtype)(((o.color))) << ((0) + 8)) & ((chtype)((((1U) << 8) - 1U)) << ((0) + 8)));
  if (o.character == '#') new |= ((chtype)((1U)) << ((12) + 8));
  if (o.character <= '\32') new |= ((chtype)((1U)) << ((14) + 8));
  if (o.bold) new |= ((chtype)((1U)) << ((13) + 8));
  wattrset(stdscr,(new));
  if (in_place) {
      printw("%c",o.character);
    } else {
      mvprintw(o.y,o.x,"%c",o.character);
      wmove(stdscr,(o.y),(o.x));
    }
  wattrset(stdscr,(old));
}

void message(char* message) {
  wmove(stdscr,(1),(0));
  wclrtoeol(stdscr);
  mvprintw(1,0,"%.*s",COLS,message);
  wmove(stdscr,(robot.y),(robot.x));
  wrefresh(stdscr);
}

